std::string Editor::sliceHandleAt(gfx::Point at,const SliceRect& r)const{const auto p=canvasDocumentPoint(at);const double scale=canvasScale(),px=p.x*scale,py=p.y*scale,l=r.x*scale,t=r.y*scale,right=(r.x+r.width)*scale,bottom=(r.y+r.height)*scale;struct H{const char* id;double x,y;};const H corners[]={{"nw",l,t},{"ne",right,t},{"sw",l,bottom},{"se",right,bottom}};for(const auto& h:corners){const bool outer=(h.id[0]=='n'?py<=h.y:py>=h.y)&&(h.id[1]=='w'?px<=h.x:px>=h.x);const int radius=(outer?3:8)*uiScale;if(std::abs(px-h.x)<=radius&&std::abs(py-h.y)<=radius)return h.id;}const H edges[]={{"n",(l+right)/2,t},{"s",(l+right)/2,bottom},{"w",l,(t+bottom)/2},{"e",right,(t+bottom)/2}};double nearest=1e100;std::string hit;for(const auto& h:edges){const auto dx=px-h.x,dy=py-h.y,d=dx*dx+dy*dy;if(std::abs(dx)<=6*uiScale&&std::abs(dy)<=6*uiScale&&d<nearest){nearest=d;hit=h.id;}}return hit;}
