 const auto initialPixels=document.pixels();event(ui::kMouseDownMessage,4,4);event(ui::kMouseMoveMessage,20,17);check(document.slices().empty()&&document.historySize()==0,"Slice creation preview mutated document");event(ui::kMouseUpMessage,20,17);check(document.slices().size()==1&&document.historySize()==1&&document.slices()[0].rect==SliceRect{4,4,17,14},"Actual slice drag creation");
 event(ui::kMouseDownMessage,30,4);event(ui::kMouseUpMessage,30,4);check(document.slices().size()==1,"Empty click must not create slice");event(ui::kMouseDownMessage,30,4);event(ui::kMouseMoveMessage,40,16);ui::KeyMessage escape(ui::kKeyDownMessage,ui::kKeyEsc,ui::kKeyNoneModifier,0,0);processSliceInput(&escape);check(document.slices().size()==1&&sliceDrag_==0&&!hasCapture(),"Escape cancels preview without history");
 document.selectAllSlices();const auto original=document.slices()[0];event(ui::kMouseDownMessage,12,10,ui::kKeyAltModifier);event(ui::kMouseMoveMessage,18,14,ui::kKeyAltModifier);check(document.slices().size()==1,"Alt copy preview mutated document");event(ui::kMouseUpMessage,18,14,ui::kKeyAltModifier);check(document.slices().size()==2&&document.slices().back().name==original.name&&document.slices().back().id!=original.id,"Alt drag commits copied slice");document.undo();check(document.slices().size()==1,"Copy undo");document.redo();check(document.slices().size()==2,"Copy redo");
 document.selectAllSlices();const auto before=document.slices();event(ui::kMouseDownMessage,13,11);event(ui::kMouseMoveMessage,15,13);event(ui::kMouseUpMessage,15,13);check(document.slices()[0].rect.x==before[0].rect.x+2&&document.slices()[1].rect.x==before[1].rect.x+2,"Multislice drag preserves offsets");document.undo();check(document.slices()==before&&document.selectedSliceIds().size()==2,"Move undo selected ranges");
